-- Move every date and timestamp (except birth dates) so the demo history ends today.
DO $$
DECLARE
    shift integer := current_date - DATE '2026-10-09';
    tbl record;
BEGIN
    IF shift = 0 THEN
        RETURN;
    END IF;
    -- One UPDATE per table so checks like finished_at >= started_at always hold.
    FOR tbl IN
        SELECT c.table_name,
               string_agg(format('%I = %I + make_interval(days => %s)', c.column_name, c.column_name, shift), ', ') AS sets
        FROM information_schema.columns c
        JOIN information_schema.tables t USING (table_schema, table_name)
        WHERE c.table_schema = 'public' AND t.table_type = 'BASE TABLE'
          AND c.data_type IN ('date', 'timestamp without time zone')
          AND c.column_name NOT IN ('birth_date', 'license_expires_on')
        GROUP BY c.table_name
    LOOP
        EXECUTE format('UPDATE %I SET %s', tbl.table_name, tbl.sets);
    END LOOP;
END $$;

COMMIT;
